import { list as keystoneList } from '@keystone-6/core'
import { denyAll } from '@keystone-6/core/access'
import { checkbox, integer, json, relationship, select, text, timestamp } from '@keystone-6/core/fields'
import { currentCapability, currentTenantItemScope, currentTenantScope, isSignedIn } from '../access'
import { trackingFields } from './trackingFields'
import { DEFAULT_STORE_LOGO_COLOR, DEFAULT_STORE_LOGO_ICON, normalizeStoreLogoColor } from '../../platform/store-settings/lib/store-logo'
import { sanitizeStoreLogoSvg } from '../utils/storeLogo'

const list=(config:any)=>keystoneList({...config,ui:{hideNavigation:true,hideCreate:true,hideDelete:true,...config.ui},graphql:{...config.graphql,maxTake:100}})

const requiredText = () => text({ validation: { isRequired: true } })
const status = (values: string[], defaultValue = values[0]) => select({ type: 'enum', options: values.map(value => ({ label: value, value })), defaultValue })
const tenant = () => relationship({ ref: 'Tenant', many: false, access: { create: denyAll, update: denyAll } })
const scopedAccess=(capability:string)=>({operation:{query:currentCapability(capability),create:denyAll,update:denyAll,delete:denyAll},filter:{query:currentTenantScope}})
const tenantAccess=scopedAccess('canManageSportsbook')

export const Tenant = list({ access: { operation: { query: isSignedIn, create: denyAll, update: denyAll, delete: denyAll }, filter:{query:currentTenantItemScope} }, fields: { name: requiredText(), slug: text({ isIndexed: 'unique' }), status: status(['ACTIVE','SUSPENDED','CLOSED']), defaultTimezone: requiredText(), supportedLocales: json(), dataResidencyRegion: text(), ...trackingFields } })
export const Brand = list({ access: tenantAccess, fields: { tenant: tenant(), name: requiredText(), domain: requiredText(), defaultLocale: requiredText(), defaultTimezone: text(), supportedLocales: json(), designTokens: json(), termsReference: text(), logoIcon: text({ defaultValue: DEFAULT_STORE_LOGO_ICON, hooks: { resolveInput: ({ resolvedData, fieldKey }: any) => { const value = resolvedData[fieldKey]; if (value === undefined || value === null || value === '') return value; return typeof value === 'string' ? sanitizeStoreLogoSvg(value) : '' }, validate: ({ inputData, resolvedData, fieldKey, addValidationError }: any) => { const submitted = inputData?.[fieldKey]; if (typeof submitted === 'string' && submitted.trim() && !resolvedData?.[fieldKey]) addValidationError('Logo must be a valid, safe SVG document') } } }), logoColor: text({ defaultValue: DEFAULT_STORE_LOGO_COLOR, hooks: { resolveInput: ({ resolvedData, fieldKey }: any) => { const value = resolvedData[fieldKey]; return value === undefined ? value : normalizeStoreLogoColor(value) } } }), status: status(['ACTIVE','INACTIVE']), ...trackingFields } })
export const Jurisdiction = list({ access: { operation: { query: currentCapability('canManageSportsbook'), create: denyAll, update: denyAll, delete: denyAll } }, fields: { code: text({ isIndexed: 'unique' }), authority: requiredText(), status: status(['PENDING','ACTIVE','INACTIVE']), ...trackingFields } })
export const OperatorJurisdiction = list({ access: tenantAccess, fields: { tenant: tenant(), jurisdiction: relationship({ ref: 'Jurisdiction' }), licenseReference: requiredText(), policyVersion: requiredText(), effectiveFrom: timestamp(), effectiveTo: timestamp(), status: status(['PENDING','ACTIVE','SUSPENDED']), ...trackingFields } })
export const Player = list({ access: scopedAccess('canManageCompliance'), fields: { tenant: tenant(), brand: relationship({ ref: 'Brand' }), subject: requiredText(), status: status(['PENDING','ACTIVE','SUSPENDED','CLOSED']), kycStatus: status(['REQUIRED','PENDING','APPROVED','REJECTED']), locale: requiredText(), timezone: text(), preferredOddsFormat: status(['DECIMAL','AMERICAN','FRACTIONAL']), marketingAllowed: checkbox({ defaultValue: false }), riskBand: status(['LOW','MEDIUM','HIGH']), ...trackingFields } })
export const PlayerLimit = list({ access: scopedAccess('canManageCompliance'), fields: { tenant: tenant(), player: relationship({ ref: 'Player' }), type: status(['DEPOSIT','STAKE','LOSS','SESSION']), period: status(['DAILY','WEEKLY','MONTHLY']), amountMinor: requiredText(), currency: requiredText(), effectiveFrom: timestamp({ validation: { isRequired: true } }), effectiveTo: timestamp(), ...trackingFields } })
export const SelfExclusion = list({ access: scopedAccess('canManageCompliance'), fields: { tenant: tenant(), player: relationship({ ref: 'Player' }), scope: requiredText(), startsAt: timestamp({ validation: { isRequired: true } }), endsAt: timestamp(), status: status(['ACTIVE','EXPIRED','REVOKED']), source: requiredText(), ...trackingFields } })

export const Sport = list({ access: scopedAccess('canTrade'), fields: { tenant: tenant(), key: requiredText(), name: requiredText(), active: checkbox({ defaultValue: true }), ...trackingFields } })
export const Competition = list({ access: scopedAccess('canTrade'), fields: { tenant: tenant(), sport: relationship({ ref: 'Sport' }), region: relationship({ ref: 'Region' }), key: requiredText(), name: requiredText(), timezone: text(), status: status(['ACTIVE','INACTIVE']), ...trackingFields } })
export const Event = list({ access: scopedAccess('canTrade'), fields: { tenant: tenant(), competition: relationship({ ref: 'Competition' }), season: relationship({ ref: 'Season' }), stage: relationship({ ref: 'CompetitionStage' }), venue: relationship({ ref: 'Venue' }), externalKey: requiredText(), name: requiredText(), startAt: timestamp({ validation: { isRequired: true } }), status: status(['SCHEDULED','LIVE','ENDED','CANCELLED','SUSPENDED']), livePhase: text(), clockSeconds: integer(), officialResultStatus: status(['NONE','PROVISIONAL','APPROVED','DISPUTED']), version: integer({ defaultValue: 1 }), ...trackingFields } })
export const Market = list({ access: scopedAccess('canTrade'), fields: { tenant: tenant(), event: relationship({ ref: 'Event' }), definition: relationship({ ref: 'MarketDefinition' }), definitionKey: requiredText(), parameters: json(), tradingMode: status(['PREMATCH','LIVE']), line: text(), marginBasisPoints: integer(), cashOutEnabled: checkbox({ defaultValue: false }), status: status(['OPEN','SUSPENDED','CLOSED','GRADED']), version: integer({ defaultValue: 1 }), ...trackingFields } })
export const Selection = list({ access: scopedAccess('canTrade'), fields: { tenant: tenant(), market: relationship({ ref: 'Market' }), key: requiredText(), label: requiredText(), status: status(['OPEN','SUSPENDED','CLOSED']), ...trackingFields } })
export const PriceSnapshot = list({ access: scopedAccess('canTrade'), fields: { tenant: tenant(), selection: relationship({ ref: 'Selection' }), providerConnection: relationship({ ref: 'ProviderConnection' }), decimalOdds: requiredText(), line: text(), sequence: requiredText(), effectiveAt: timestamp({ validation: { isRequired: true } }), receivedAt: timestamp({ validation: { isRequired: true } }), rawEnvelope: relationship({ ref: 'RawEnvelope' }), status: status(['OPEN','SUSPENDED']), ...trackingFields } })

export const Quote = list({ access: scopedAccess('canManageRisk'), fields: { tenant: tenant(), player: relationship({ ref: 'Player' }), selection: relationship({ ref: 'Selection' }), priceSnapshot: relationship({ ref: 'PriceSnapshot' }), structure: status(['STRAIGHT','PARLAY','SYSTEM','ROUND_ROBIN','TEASER','EACH_WAY']), promotion: relationship({ ref: 'Promotion' }), legCount: integer({ defaultValue: 1 }), partCount: integer({ defaultValue: 1 }), stakeMinor: requiredText(), potentialReturnMinor: text(), currency: requiredText(), decimalOdds: requiredText(), priceChangeConsent: status(['EXACT','ACCEPT_BETTER','ACCEPT_WITHIN_TOLERANCE']), liveDelayMs: integer({ defaultValue: 0 }), expiresAt: timestamp({ validation: { isRequired: true } }), termsHash: requiredText(), policyVersion: requiredText(), ...trackingFields } })
export const Wager = list({ access: scopedAccess('canManageRisk'), fields: { tenant: tenant(), player: relationship({ ref: 'Player' }), quote: relationship({ ref: 'Quote' }), legalEntity: relationship({ ref: 'LegalEntity' }), operatorJurisdiction: relationship({ ref: 'OperatorJurisdiction' }), brand: relationship({ ref: 'Brand' }), channel: relationship({ ref: 'OperatorChannel' }), structure: status(['STRAIGHT','PARLAY','SYSTEM','ROUND_ROBIN','TEASER','EACH_WAY']), promotion: relationship({ ref: 'Promotion' }), bonusAward: relationship({ ref: 'BonusAward' }), version: integer({ defaultValue: 1 }), idempotencyKey: requiredText(), stakeMinor: requiredText(), potentialReturnMinor: requiredText(), maxPayoutMinor: text(), currency: requiredText(), termsHash: requiredText(), priceChangeConsent: status(['EXACT','ACCEPT_BETTER','ACCEPT_WITHIN_TOLERANCE']), liveDelayMs: integer({ defaultValue: 0 }), requestedAt: timestamp(), status: status(['PENDING','DELAYED','ACCEPTED','REJECTED','OPEN','PARTIALLY_CASHED_OUT','CASHED_OUT','GRADED','SETTLED','VOID']), acceptedAt: timestamp(), ...trackingFields } })
export const WagerLeg = list({ access: scopedAccess('canManageRisk'), fields: { tenant: tenant(), wager: relationship({ ref: 'Wager' }), wagerPart: relationship({ ref: 'WagerPart' }), legIndex: integer(), eventKey: requiredText(), marketKey: requiredText(), selectionKey: requiredText(), snapshotId: requiredText(), decimalOdds: requiredText(), line: text(), ruleVersion: requiredText(), correlationGroupKey: text(), live: checkbox({ defaultValue: false }), ...trackingFields } })
export const AcceptanceDecision = list({ access: scopedAccess('canManageRisk'), fields: { tenant: tenant(), wager: relationship({ ref: 'Wager' }), quote: relationship({ ref: 'Quote' }), accepted: checkbox({ defaultValue: false }), rejectionCode: text(), gateResults: json(), inputHash: requiredText(), ...trackingFields } })
export const ResultVersion = list({ access: scopedAccess('canManageRisk'), fields: { tenant: tenant(), event: relationship({ ref: 'Event' }), providerConnection: relationship({ ref: 'ProviderConnection' }), version: integer({ validation: { isRequired: true } }), status: status(['PENDING','APPROVED','REJECTED','SUPERSEDED']), payload: json(), payloadHash: requiredText(), approvedAt: timestamp(), ...trackingFields } })
export const Settlement = list({ access: scopedAccess('canManageRisk'), fields: { tenant: tenant(), wager: relationship({ ref: 'Wager' }), resultVersion: relationship({ ref: 'ResultVersion' }), settlementRun: relationship({ ref: 'SettlementRun' }), version: integer({ validation: { isRequired: true } }), outcome: status(['WIN','LOSS','PUSH','VOID','DEAD_HEAT','PARTIAL']), grossPayoutMinor: text(), taxMinor: text(), payoutMinor: requiredText(), inputHash: requiredText(), journalTransaction: relationship({ ref: 'JournalTransaction' }), reversalOf: relationship({ ref: 'Settlement' }), ...trackingFields } })

export const LedgerAccount = list({ access: scopedAccess('canManageFinance'), fields: { tenant: tenant(), player: relationship({ ref: 'Player' }), key: requiredText(), accountClass: status(['ASSET','LIABILITY','REVENUE','EXPENSE','EQUITY']), currency: requiredText(), status: status(['ACTIVE','FROZEN','CLOSED']), ...trackingFields } })
export const JournalTransaction = list({ access: scopedAccess('canManageFinance'), fields: { tenant: tenant(), type: requiredText(), idempotencyKey: requiredText(), correlationId: requiredText(), status: status(['POSTED','REVERSED']), reversalOf: relationship({ ref: 'JournalTransaction' }), effectiveAt: timestamp({ validation: { isRequired: true } }), ...trackingFields } })
export const JournalEntry = list({ access: scopedAccess('canManageFinance'), fields: { tenant: tenant(), transaction: relationship({ ref: 'JournalTransaction' }), account: relationship({ ref: 'LedgerAccount' }), side: status(['DEBIT','CREDIT']), amountMinor: requiredText(), currency: requiredText(), ...trackingFields } })
export const Hold = list({ access: scopedAccess('canManageFinance'), fields: { tenant: tenant(), account: relationship({ ref: 'LedgerAccount' }), purposeType: requiredText(), purposeId: requiredText(), amountMinor: requiredText(), status: status(['ACTIVE','CAPTURED','RELEASED','EXPIRED']), expiresAt: timestamp(), version: integer({ defaultValue: 1 }), ...trackingFields } })

export const ProviderConnection = list({ access: scopedAccess('canManageIntegrations'), fields: { tenant: tenant(), legalEntity: relationship({ ref: 'LegalEntity' }), jurisdiction: relationship({ ref: 'Jurisdiction' }), adapterId: requiredText(), adapterVersion: requiredText(), configReference: requiredText(), secretReference: text(), dataResidencyRegion: text(), failoverPriority: integer({ defaultValue: 100 }), capabilities: json(), certificationStatus: status(['SANDBOX','PENDING','CERTIFIED','SUSPENDED']), status: status(['ACTIVE','DEGRADED','DISABLED']), ...trackingFields } })
export const RawEnvelope = list({ access: scopedAccess('canManageIntegrations'), fields: { tenant: tenant(), providerConnection: relationship({ ref: 'ProviderConnection' }), direction: status(['INBOUND','OUTBOUND']), externalId: requiredText(), schemaVersion: requiredText(), installationRevision: text(), payload: json(), payloadHash: requiredText(), receivedAt: timestamp({ validation: { isRequired: true } }), ...trackingFields } })
export const InboxMessage = list({ access: scopedAccess('canManageIntegrations'), fields: { tenant: tenant(), rawEnvelope: relationship({ ref: 'RawEnvelope' }), messageKey: requiredText(), type: requiredText(), status: status(['PENDING','PROCESSING','COMPLETED','DEAD']), attempts: integer({ defaultValue: 0 }), availableAt: timestamp(), leaseUntil: timestamp(), leaseOwner: text(), lastError: text(), ...trackingFields } })
export const OutboxMessage = list({ access: scopedAccess('canManageIntegrations'), fields: { tenant: tenant(), aggregateType: requiredText(), aggregateId: requiredText(), eventType: requiredText(), payload: json(), status: status(['PENDING','PROCESSING','COMPLETED','DEAD']), attempts: integer({ defaultValue: 0 }), maxAttempts: integer({ defaultValue: 10 }), availableAt: timestamp(), leaseUntil: timestamp(), leaseOwner: text(), lastError: text(), ...trackingFields } })
export const DeadLetter = list({ access: scopedAccess('canManageIntegrations'), fields: { tenant: tenant(), sourceType: requiredText(), sourceId: requiredText(), reason: requiredText(), attempts: integer(), payloadReference: text(), resolvedAt: timestamp(), ...trackingFields } })
export const AuditEvent = list({ access: scopedAccess('canReadAudit'), fields: { tenant: tenant(), actorId: requiredText(), action: requiredText(), targetType: requiredText(), targetId: requiredText(), reason: text(), payloadHash: requiredText(), previousHash: text(), hash: requiredText(), ...trackingFields } })
