export const MarketGrade=f({market:rel('Market'),resultVersion:rel('ResultVersion'),ruleVersion:t(),outcome:t(),factorNumerator:text(),factorDenominator:text(),trace:json(),inputHash:t()},scopedAccess('canManageRisk'))
